<?php require __DIR__.'/config/config.php'; require __DIR__.'/config/helpers.php';
$ville=trim($_GET['ville']??''); $arrivee=$_GET['arrivee']??''; $depart=$_GET['depart']??''; $personnes=max(1,(int)($_GET['personnes']??2));
$sql="SELECT h.*, (SELECT fichier FROM hotel_photos p WHERE p.hotel_id=h.id ORDER BY p.principale DESC,p.id DESC LIMIT 1) photo, (SELECT MIN(r.prix_nuit) FROM rooms r WHERE r.hotel_id=h.id AND r.actif=1) prix, (SELECT ROUND(AVG(rv.note),1) FROM reviews rv WHERE rv.hotel_id=h.id) note FROM hotels h WHERE h.statut='valide'"; $params=[]; if($ville!==''){ $sql.=' AND (h.ville LIKE ? OR h.commune LIKE ? OR h.nom LIKE ?)'; $params=["%$ville%","%$ville%","%$ville%"]; } if($arrivee && $depart && $depart>$arrivee){ $sql.=" AND EXISTS(SELECT 1 FROM rooms r WHERE r.hotel_id=h.id AND r.actif=1 AND r.capacite>=? AND NOT EXISTS(SELECT 1 FROM reservations b WHERE b.room_id=r.id AND b.statut NOT IN ('annulee','refusee') AND b.date_arrivee < ? AND b.date_depart > ?))"; $params[]=$personnes; $params[]=$depart; $params[]=$arrivee; } $sql.=' ORDER BY h.created_at DESC LIMIT 60'; $q=$pdo->prepare($sql); $q->execute($params); $hotels=$q->fetchAll();
$pageTitle='Réservez votre prochain séjour'; require __DIR__.'/includes/header.php'; ?>
<section class="hero"><div class="container"><span class="eyebrow">VOTRE SÉJOUR COMMENCE ICI</span><h1>Trouvez l'hôtel<br><em>qui vous ressemble.</em></h1><p>Découvrez des établissements et réservez en toute simplicité, partout en Côte d’Ivoire.</p><form class="searchbar" method="get"><div><label>Destination</label><input name="ville" value="<?=e($ville)?>" placeholder="Abidjan, Bouaké, Yamoussoukro…"></div><div><label>Arrivée</label><input type="date" name="arrivee" min="<?=date('Y-m-d')?>" value="<?=e($arrivee)?>"></div><div><label>Départ</label><input type="date" name="depart" min="<?=date('Y-m-d')?>" value="<?=e($depart)?>"></div><div><label>Voyageurs</label><select name="personnes"><?php for($i=1;$i<=10;$i++):?><option value="<?=$i?>" <?=$personnes===$i?'selected':''?>><?=$i?> personne<?=$i>1?'s':''?></option><?php endfor;?></select></div><button class="btn btn-primary">Rechercher <span>→</span></button></form></div></section>
<section class="container section"><div class="section-heading"><div><span class="eyebrow">SÉLECTION HOTELCONNECT</span><h2>Des hôtels à découvrir</h2><p>Des lieux pour vos voyages, vos vacances et vos déplacements.</p></div><span class="count-pill"><?=count($hotels)?> établissement(s)</span></div><div class="hotel-grid"><?php foreach($hotels as $h):?><article class="hotel-card"><a class="hotel-image" href="hotel.php?id=<?=$h['id']?>"><?php if($h['photo']):?><img src="<?=e(BASE_URL.'/uploads/hotels/'.$h['photo'])?>" alt="<?=e($h['nom'])?>"><?php else:?><div class="image-placeholder">HC</div><?php endif;?><span class="image-tag"><?=e($h['categorie'])?></span></a><div class="hotel-info"><div class="hotel-meta"><span><?=str_repeat('★',(int)$h['etoiles'])?></span><span><?= $h['note']!==null ? '★ '.e($h['note']).'/5' : 'Nouvel établissement' ?></span></div><h3><a href="hotel.php?id=<?=$h['id']?>"><?=e($h['nom'])?></a></h3><p class="location">⌖ <?=e($h['commune'] ? $h['commune'].', ' : '').e($h['ville'])?></p><div class="hotel-bottom"><div><?php if($h['prix']!==null):?><strong><?=money($h['prix'])?></strong><small>/ nuit à partir de</small><?php else:?><small>Tarifs à venir</small><?php endif;?></div><a class="text-link" href="hotel.php?id=<?=$h['id']?>">Découvrir ↗</a></div></div></article><?php endforeach;?></div><?php if(!$hotels):?><div class="empty-state"><h3>Aucun hôtel trouvé pour le moment</h3><p>Essayez une autre destination ou revenez bientôt.</p></div><?php endif;?></section>
